/**
 * Generates src/editor/markdown/emoji.generated.ts — the GitHub emoji
 * shortcode table the Markdown renderer expands `:+1:`-style references
 * with.
 *
 * SOURCE OF TRUTH: github/gemoji's db/emoji.json (https://github.com/
 * github/gemoji) — the same table GitHub's own pipeline expands shortcodes
 * from, which is the parity target for Padify's GFM rendering. Every alias
 * maps to its emoji's literal codepoints; aliases are lowercase ASCII
 * ([a-z0-9_+-]+ by the database's own convention), so the lookup needs no
 * case folding.
 *
 * The generated file is checked in — CI never touches the network. Re-run
 * this script only when the emoji table itself needs a refresh:
 *
 *   node scripts/gen-md-emoji.mjs
 */
import { writeFileSync } from 'node:fs';

const SOURCE_URL = 'https://raw.githubusercontent.com/github/gemoji/master/db/emoji.json';
const OUT = new URL('../src/editor/markdown/emoji.generated.ts', import.meta.url);

const response = await fetch(SOURCE_URL);
if (!response.ok) {
  throw new Error(`gemoji db fetch failed: ${response.status} ${response.statusText}`);
}
const table = await response.json();

const entries = [];
for (const entry of table) {
  if (!entry.emoji) {
    continue; // entries without a literal (flag pairs) are not shortcode targets
  }
  // Per-codepoint escapes (no raw non-ASCII in the table): identical to
  // the entities table's convention, and immune to editor encoding games.
  const literal = [...entry.emoji].map((ch) => `\\u{${ch.codePointAt(0).toString(16)}}`).join('');
  for (const alias of entry.aliases) {
    entries.push([alias, literal]);
  }
}
entries.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));

const pairs = entries.map(([name, literal]) => `  ['${name}', '${literal}'],`).join('\n');
const body = pairs === '' ? '' : `\n${pairs.slice(0, -1)}\n`;

const banner = `/**
 * The GitHub emoji shortcode table — GENERATED by
 * scripts/gen-md-emoji.mjs from github/gemoji's db/emoji.json
 * (${SOURCE_URL}). DO NOT EDIT.
 *
 * \`:name:\` expands to the emoji's literal codepoints everywhere inline
 * text renders (never inside code spans, link destinations, autolinks or
 * raw HTML — those are byte-literal zones). Values are per-codepoint
 * escapes (no raw non-ASCII bytes in source), consumed as a plain
 * Map<string, string> by the renderer's inline pass.
 */
export const GEMOJI: ReadonlyMap<string, string> = new Map([${body}]);
`;

writeFileSync(OUT, banner);
console.log(`wrote ${entries.length} shortcode entries to ${OUT.pathname}`);
